using JTradeERP.Application.Common.Exceptions;using JTradeERP.Application.Common.Inventory;using JTradeERP.Application.Common.Persistence;using JTradeERP.Application.Common.Security;using JTradeERP.Domain.Inventory;using MediatR;
namespace JTradeERP.Application.Features.Inventory.Adjustments.ReverseStockAdjustment;
public sealed class ReverseStockAdjustmentHandler(IApplicationDbContext db,IStockPostingService stock,ICurrentUserService actor,IClock clock):IRequestHandler<ReverseStockAdjustmentCommand,ReverseStockAdjustmentResponse>
{
 public async Task<ReverseStockAdjustmentResponse> Handle(ReverseStockAdjustmentCommand r,CancellationToken ct){var x=db.StockAdjustments.SingleOrDefault(x=>x.Id==r.Id)??throw new NotFoundException("Stock adjustment was not found.");var original=db.StockLedgerEntries.SingleOrDefault(l=>l.SourceDocumentType=="StockAdjustment"&&l.SourceDocumentId==x.Id&&l.MovementType==StockMovementType.Adjustment)??throw new ConflictException("Only posted adjustments can be reversed.");var oldReversal=db.StockLedgerEntries.SingleOrDefault(l=>l.ReversalOfLedgerEntryId==original.Id);if(oldReversal is not null)return new(StockAdjustmentMapper.ToResponse(x),oldReversal.Id,original.Id);if(x.Status!=InventoryDocumentStatus.Posted)throw new ConflictException("Only posted adjustments can be reversed.");var actorId=actor.UserId??throw new AuthenticationFailureException();var reversal=stock.Reverse(original,x.Id,"StockAdjustmentReversal",actorId,InventoryPostingMetadata.CorrelationId);x.MarkReversed(clock.UtcNow,actorId);SecurityAuditWriter.Add(db,actorId,"StockAdjustmentReversed","StockAdjustment",x.Id.ToString(),"Posted","Reversed");await db.SaveChangesAsync(ct);return new(StockAdjustmentMapper.ToResponse(x),reversal.Id,original.Id);}
}
